import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

@SpringBootTest
class ContactViewTest extends SpringBrowserlessTest {

    private TextField name;
    private EmailField email;
    private TextField phone;
    private TextArea message;
    private Button send;
    private RouterLink aboutLink;
    private Grid<Message> grid;

    @BeforeEach
    void setUpView() {
        initVaadinEnvironment();
        navigate(ContactView.class);
        name = $(TextField.class).withLabel("Name").single();
        email = $(EmailField.class).withLabel("Email").single();
        phone = $(TextField.class).withLabel("Phone").single();
        message = $(TextArea.class).withLabel("Message").single();
        send = $(Button.class).withText("Send").single();
        aboutLink = $(RouterLink.class).withText("About").single();
        grid = findGrid();
    }

    @AfterEach
    void tearDownView() {
        cleanVaadinEnvironment();
    }

    @SuppressWarnings("unchecked")
    private Grid<Message> findGrid() {
        return (Grid<Message>) (Grid<?>) $(Grid.class).single();
    }

    private int rowCount() {
        return test(grid).size();
    }

    @Test
    void emptyFormFailsValidationAndDoesNotSend() {
        int before = rowCount();
        test(send).click();

        assertTrue(name.isInvalid());
        assertEquals("Name is required", name.getErrorMessage());
        assertTrue(email.isInvalid());
        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
        assertTrue(message.isInvalid());
        assertEquals("Message is required", message.getErrorMessage());
        assertEquals(before, rowCount());
        assertTrue(send.isEnabled());
    }

    @Test
    void invalidEmailIsRejected() {
        test(name).setValue("Ada");
        test(email).setValue("not-an-email");
        test(message).setValue("Hello there");
        test(send).click();

        assertTrue(email.isInvalid());
        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
    }

    @Test
    void phoneAloneIsEnoughToValidate() {
        test(name).setValue("Ada");
        test(phone).setValue("123456");
        test(message).setValue("Hello there");
        int before = rowCount();
        test(send).click();

        assertFalse(email.isInvalid());
        assertEquals(before + 1, rowCount());
    }

    @Test
    void tooLongMessageIsRejected() {
        test(name).setValue("Ada");
        test(email).setValue("ada@example.com");
        test(message).setValue("a".repeat(501));
        test(send).click();

        assertTrue(message.isInvalid());
        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
    }

