+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final Pattern EMAIL_PATTERN = Pattern.compile("^[A-Za-z0-9+_.-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$");
+    private static final int MAX_MESSAGE_LENGTH = 500;
+
+    private final MessageService messageService;
+
+    private final TextField nameField = new TextField("Name");
+    private final EmailField emailField = new EmailField("Email");
+    private final TextField phoneField = new TextField("Phone");
+    private final TextArea messageField = new TextArea("Message");
+    private final Button sendButton = new Button("Send");
+    private final Grid<Message> grid = new Grid<>(Message.class, false);
+
+    public ContactView(MessageService messageService) {
+        this.messageService = messageService;
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        sendButton.addClickListener(e -> send());
+        sendButton.addClickShortcut(Key.ENTER);
+
+        for (var field : java.util.List.of(nameField, emailField, phoneField, messageField)) {
+            field.addValueChangeListener(e -> sendButton.setEnabled(true));
+        }
+
+        add(new VerticalLayout(nameField, emailField, phoneField, messageField, new HorizontalLayout(sendButton)));
+
+        grid.addColumn(Message::name).setHeader("Name");
+        grid.addColumn(Message::email).setHeader("Email");
+        grid.addColumn(Message::phone).setHeader("Phone");
+        grid.addColumn(Message::message).setHeader("Message");
+        add(grid);
+
+        refreshGrid();
+    }
+
+    private void refreshGrid() {
+        grid.setItems(messageService.findAllNewestFirst());
+    }
+
+    private void send() {
+        if (!validate()) {
+            return;
+        }
+
+        messageService.send(nameField.getValue(), emailField.getValue(), phoneField.getValue(), messageField.getValue());
+        Notification.show("Message sent");
+        refreshGrid();
+        clearForm();
+        sendButton.setEnabled(false);
+    }
+
+    private void clearForm() {
+        nameField.clear();
+        emailField.clear();
+        phoneField.clear();
+        messageField.clear();
+    }
+
+    private boolean validate() {
+        boolean valid = true;
+
+        if (nameField.getValue().isBlank()) {
+            nameField.setInvalid(true);
+            nameField.setErrorMessage("Name is required");
+            valid = false;
+        } else {
+            nameField.setInvalid(false);
+        }
+
+        String email = emailField.getValue();
+        String phone = phoneField.getValue();
+        if (!email.isBlank() && !EMAIL_PATTERN.matcher(email).matches()) {
+            emailField.setInvalid(true);
+            emailField.setErrorMessage("Enter a valid e-mail address");
+            valid = false;
+        } else if (email.isBlank() && phone.isBlank()) {
+            emailField.setInvalid(true);
+            emailField.setErrorMessage("Give an e-mail address or a phone number");
+            valid = false;
+        } else {
+            emailField.setInvalid(false);
+        }
+
+        String message = messageField.getValue();
+        if (message.isBlank()) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message is required");
+            valid = false;
+        } else if (message.length() > MAX_MESSAGE_LENGTH) {
+            messageField.setInvalid(true);
+            messageField.setErrorMessage("Message must be at most 500 characters");
+            valid = false;
+        } else {
+            messageField.setInvalid(false);
+        }
+
+        return valid;
+    }
+
+    private boolean hasUnsavedInput() {
+        return !nameField.getValue().isEmpty() || !emailField.getValue().isEmpty()
+                || !phoneField.getValue().isEmpty() || !messageField.getValue().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (hasUnsavedInput()) {
+            BeforeLeaveEvent.ContinueNavigationAction action = event.postpone();
+            confirmDiscard(action);
+        }
+    }
+
+    private void confirmDiscard(BeforeLeaveEvent.ContinueNavigationAction action) {
+        Dialog dialog = new Dialog();
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+
+        dialog.add(new Paragraph("You have unsaved changes. Leave without sending the message?"));
+
+        Button keepEditing = new Button("Keep editing", e -> dialog.close());
+        Button discard = new Button("Discard", e -> {
+            dialog.close();
+            action.proceed();
+        });
+        dialog.getFooter().add(keepEditing, discard);
+
+        dialog.open();
+    }
+}
