+package com.example.contact;
+
+import com.microsoft.playwright.Locator;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+import org.springframework.boot.test.web.server.LocalServerPort;
+import org.vaadin.addons.dramafinder.AbstractBasePlaywrightIT;
+import org.vaadin.addons.dramafinder.element.ButtonElement;
+import org.vaadin.addons.dramafinder.element.DialogElement;
+import org.vaadin.addons.dramafinder.element.EmailFieldElement;
+import org.vaadin.addons.dramafinder.element.GridElement;
+import org.vaadin.addons.dramafinder.element.NotificationElement;
+import org.vaadin.addons.dramafinder.element.TextAreaElement;
+import org.vaadin.addons.dramafinder.element.TextFieldElement;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Override
+    public String getView() {
+        return "/contact";
+    }
+
+    @Test
+    void headingAndFormAreShown() {
+        assertEquals("Contact", page.locator("h1").textContent());
+        assertTrue(TextFieldElement.getByLabel(page, "Name").isVisible());
+        assertTrue(ButtonElement.getByText(page, "Send").isVisible());
+    }
+
+    @Test
+    void validationErrorsAppearOnEmptySubmit() {
+        ButtonElement.getByText(page, "Send").click();
+
+        TextFieldElement name = TextFieldElement.getByLabel(page, "Name");
+        name.assertInvalid();
+        name.assertErrorMessage("Name is required");
+
+        EmailFieldElement email = EmailFieldElement.getByLabel(page, "Email");
+        email.assertInvalid();
+        email.assertErrorMessage("Give an e-mail address or a phone number");
+
+        TextAreaElement message = TextAreaElement.getByLabel(page, "Message");
+        message.assertInvalid();
+        message.assertErrorMessage("Message is required");
+    }
+
+    @Test
+    void sendingAValidMessageShowsNotificationAndRow() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Ada Lovelace");
+        EmailFieldElement.getByLabel(page, "Email").setValue("ada@example.com");
+        TextAreaElement.getByLabel(page, "Message").setValue("Hello from the browser test");
+
+        ButtonElement send = ButtonElement.getByText(page, "Send");
+        send.click();
+
+        NotificationElement notification = NotificationElement.getByText(page, "Message sent");
+        notification.assertOpen();
+
+        assertEquals("", TextFieldElement.getByLabel(page, "Name").getValue());
+        assertFalse(send.isEnabled());
+
+        GridElement grid = GridElement.get(page);
+        assertTrue(grid.getTotalRowCount() >= 1);
+    }
+
+    @Test
+    void leavingWithUnsavedInputAsksAndDiscardNavigates() {
+        TextFieldElement.getByLabel(page, "Name").setValue("Someone");
+
+        Locator aboutLink = page.getByText("About");
+        aboutLink.click();
+
+        DialogElement dialog = new DialogElement(page);
+        dialog.assertOpen();
+
+        ButtonElement.getByText(dialog.getFooterLocator(), "Discard").click();
+
+        page.locator("h1").getByText("About").waitFor();
+        assertEquals("About", page.locator("h1").textContent());
+    }
+}
