+package com.example.contact;
+
+import com.vaadin.browserless.SpringBrowserlessTest;
+import com.vaadin.flow.component.Key;
+import com.vaadin.flow.component.button.Button;
+import com.vaadin.flow.component.dialog.Dialog;
+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+import org.junit.jupiter.api.AfterEach;
+import org.junit.jupiter.api.BeforeEach;
+import org.junit.jupiter.api.Test;
+import org.springframework.boot.test.context.SpringBootTest;
+
+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertFalse;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    private TextField name;
+    private EmailField email;
+    private TextField phone;
+    private TextArea message;
+    private Button send;
+    private RouterLink aboutLink;
+    private Grid<Message> grid;
+
+    @BeforeEach
+    void setUpView() {
+        initVaadinEnvironment();
+        navigate(ContactView.class);
+        name = $(TextField.class).withLabel("Name").single();
+        email = $(EmailField.class).withLabel("Email").single();
+        phone = $(TextField.class).withLabel("Phone").single();
+        message = $(TextArea.class).withLabel("Message").single();
+        send = $(Button.class).withText("Send").single();
+        aboutLink = $(RouterLink.class).withText("About").single();
+        grid = findGrid();
+    }
+
+    @AfterEach
+    void tearDownView() {
+        cleanVaadinEnvironment();
+    }
+
+    @SuppressWarnings("unchecked")
+    private Grid<Message> findGrid() {
+        return (Grid<Message>) (Grid<?>) $(Grid.class).single();
+    }
+
+    private int rowCount() {
+        return test(grid).size();
+    }
+
+    @Test
+    void emptyFormFailsValidationAndDoesNotSend() {
+        int before = rowCount();
+        test(send).click();
+
+        assertTrue(name.isInvalid());
+        assertEquals("Name is required", name.getErrorMessage());
+        assertTrue(email.isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email.getErrorMessage());
+        assertTrue(message.isInvalid());
+        assertEquals("Message is required", message.getErrorMessage());
+        assertEquals(before, rowCount());
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void invalidEmailIsRejected() {
+        test(name).setValue("Ada");
+        test(email).setValue("not-an-email");
+        test(message).setValue("Hello there");
+        test(send).click();
+
+        assertTrue(email.isInvalid());
+        assertEquals("Enter a valid e-mail address", email.getErrorMessage());
+    }
+
+    @Test
+    void phoneAloneIsEnoughToValidate() {
+        test(name).setValue("Ada");
+        test(phone).setValue("123456");
+        test(message).setValue("Hello there");
+        int before = rowCount();
+        test(send).click();
+
+        assertFalse(email.isInvalid());
+        assertEquals(before + 1, rowCount());
+    }
+
+    @Test
+    void tooLongMessageIsRejected() {
+        test(name).setValue("Ada");
+        test(email).setValue("ada@example.com");
+        test(message).setValue("a".repeat(501));
+        test(send).click();
+
+        assertTrue(message.isInvalid());
+        assertEquals("Message must be at most 500 characters", message.getErrorMessage());
+    }
+
+    @Test
+    void validSendClearsFormNotifiesAndDisablesSend() {
+        test(name).setValue("Ada Lovelace");
+        test(email).setValue("ada@example.com");
+        test(message).setValue("Hello there");
+        int before = rowCount();
+
+        test(send).click();
+
+        Notification notification = $(Notification.class).single();
+        assertTrue(test(notification).getText().contains("Message sent"));
+
+        assertEquals("", name.getValue());
+        assertEquals("", email.getValue());
+        assertEquals("", message.getValue());
+        assertEquals(before + 1, rowCount());
+        assertFalse(send.isEnabled());
+
+        test(name).setValue("x");
+        assertTrue(send.isEnabled());
+    }
+
+    @Test
+    void enterKeySendsValidForm() {
+        test(name).setValue("Grace Hopper");
+        test(email).setValue("grace@example.com");
+        test(message).setValue("Hi");
+        int before = rowCount();
+
+        fireShortcut(Key.ENTER);
+
+        assertEquals(before + 1, rowCount());
+    }
+
+    @Test
+    void navigatingAwayWithUnsavedInputAsksFirstAndKeepEditingStays() {
+        test(name).setValue("Someone");
+
+        test(aboutLink).click();
+
+        Dialog dialog = $(Dialog.class).single();
+        Button keepEditing = $(Button.class, dialog).withText("Keep editing").single();
+        test(keepEditing).click();
+
+        assertEquals("Someone", name.getValue());
+        assertTrue(getCurrentView() instanceof ContactView);
+    }
+
+    @Test
+    void navigatingAwayWithUnsavedInputDiscardProceeds() {
+        test(name).setValue("Someone");
+
+        test(aboutLink).click();
+
+        Dialog dialog = $(Dialog.class).single();
+        Button discard = $(Button.class, dialog).withText("Discard").single();
+        test(discard).click();
+
+        assertTrue(getCurrentView() instanceof AboutView);
+    }
+
+    @Test
+    void navigatingAwayWithEmptyFormDoesNotAsk() {
+        test(aboutLink).click();
+
+        assertTrue(getCurrentView() instanceof AboutView);
+    }
+}
